enum AccountError: Error { case invalidState, invalidAmount, belowFloor }

struct Account {
    let floor: Decimal
    private(set) var balance: Decimal

    init(floor: Decimal, balance: Decimal = 0) throws {
        guard floor >= 0, balance >= floor else { throw AccountError.invalidState }
        self.floor = floor
        self.balance = balance
    }

    mutating func withdraw(_ amount: Decimal) throws {
        guard amount > 0 else { throw AccountError.invalidAmount }
        let nextBalance = balance - amount
        guard nextBalance >= floor else { throw AccountError.belowFloor }
        balance = nextBalance
        assert(balance >= floor, "invariant: \(balance) < \(floor)")
    }
}
